# Generated by scripts/packaging/formula.ts in ome-labs/ome for each release; do not edit by hand.
class Ome < Formula
  desc "Private k-of-n multisig on Aztec with threshold viewing"
  homepage "https://ome.network"
  version "0.1.0"
  license "Apache-2.0"

  depends_on "node@24"

  on_macos do
    on_arm do
      url "https://github.com/ome-labs/ome/releases/download/v0.1.0/ome-0.1.0-darwin-arm64.tar.gz"
      sha256 "1c613ca915c2510ea32a17222e770e04e6ac8f7cbd34575d960dc2b3486dc517"
    end
  end

  on_linux do
    on_intel do
      url "https://github.com/ome-labs/ome/releases/download/v0.1.0/ome-0.1.0-linux-x64.tar.gz"
      sha256 "e6bef3b827f21112231ad532d5a728272a3cd64674600c519cb6f9d944997280"
    end
    on_arm do
      url "https://github.com/ome-labs/ome/releases/download/v0.1.0/ome-0.1.0-linux-arm64.tar.gz"
      sha256 "b0b27ffebb106f906ae960206fedda481c27b9003015dd97d2204705fe777130"
    end
  end

  def install
    libexec.install Dir["*"]
    # The daemon runs with Homebrew's Node, also when a login service starts it without PATH.
    inreplace libexec/"bin/omed", 'node_default=""', %Q(node_default="#{formula_opt_bin("node@24")}/node")
    bin.install_symlink libexec/"bin/ome", libexec/"bin/omed", libexec/"bin/ome-keeper"
  end

  def caveats
    <<~EOS
      Create a profile with:
        ome init
      Keep your keeper online while your laptop sleeps by running the daemon as a login service:
        ome daemon install-service
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/ome --version")
    assert_match version.to_s, shell_output("#{bin}/ome-keeper --version")
  end
end
